        for c in range(len(g[0])):
            if g[r][c] and (r,c) not in seen:
                col=g[r][c]; stack=[(r,c)]; comp=[]
                seen.add((r,c))
                while stack:
                    a,b=stack.pop(); comp.append((a,b))
                    for dr in(-1,0,1):
                        for dc in(-1,0,1):
                            p=(a+dr,b+dc)
                            if 0<=p[0]<len(g) and 0<=p[1]<len(g[0]) and g[p[0]][p[1]]==col and p not in seen:
